[MemoryDiagnoser]
public class ConcatBenchmarks
{
    private readonly string[] _parts = Enumerable.Range(0, 50)
        .Select(i => i.ToString())
        .ToArray();

    [Benchmark(Baseline = true)]
    public string WithPlus()
    {
        var result = "";

        foreach (var part in _parts) result += part;

        return result;
    }

    [Benchmark]
    public string WithBuilder()
    {
        var sb = new StringBuilder();

        foreach (var part in _parts) sb.Append(part);

        return sb.ToString();
    }
}

// dotnet run -c Release
